export const styles = "@layer base{html,body{margin:0;padding:0;}body{overscroll-behavior:none;}main>:first-child{margin-top:0!important;}main>:last-child{margin-bottom:0!important;}}::-webkit-scrollbar{display:none;}.material-symbols-outlined{font-variation-settings:'FILL' 0,'wght' 400,'GRAD' 0,'opsz' 24;}";
export const script = "\n    (function initProductCatalogManagement() {\n      const selectAll = document.getElementById('selectAllCheckbox');\n      const rowCheckboxes = document.querySelectorAll('.row-checkbox');\n      const bulkBar = document.getElementById('bulkActionsBar');\n      const countBadge = document.getElementById('selectedCountBadge');\n      const clearBtn = document.getElementById('clearSelectionBtn');\n\n      function updateBulkStatus() {\n        let checkedCount = 0;\n        rowCheckboxes.forEach(cb => {\n          if (cb.checked) checkedCount++;\n        });\n\n        if (countBadge) countBadge.textContent = checkedCount;\n\n        if (checkedCount > 0) {\n          if (bulkBar) {\n            bulkBar.classList.remove('hidden');\n            bulkBar.classList.add('flex');\n          }\n        } else {\n          if (bulkBar) {\n            bulkBar.classList.add('hidden');\n            bulkBar.classList.remove('flex');\n          }\n        }\n\n        if (selectAll) {\n          selectAll.checked = checkedCount === rowCheckboxes.length && rowCheckboxes.length > 0;\n          selectAll.indeterminate = checkedCount > 0 && checkedCount < rowCheckboxes.length;\n        }\n      }\n\n      if (selectAll) {\n        selectAll.addEventListener('change', (e) => {\n          const isChecked = e.target.checked;\n          rowCheckboxes.forEach(cb => {\n            cb.checked = isChecked;\n          });\n          updateBulkStatus();\n        });\n      }\n\n      rowCheckboxes.forEach(cb => {\n        cb.addEventListener('change', updateBulkStatus);\n      });\n\n      if (clearBtn) {\n        clearBtn.addEventListener('click', () => {\n          rowCheckboxes.forEach(cb => cb.checked = false);\n          if (selectAll) {\n            selectAll.checked = false;\n            selectAll.indeterminate = false;\n          }\n          updateBulkStatus();\n        });\n      }\n\n      // Initial call to calibrate checked rows\n      updateBulkStatus();\n    })();\n  ";
export const bodyClass = "bg-background font-body-md text-body-md text-on-surface antialiased";
export const scope = "mk-adminProducts";
